//! Original 24-unit vector artwork. Array order matches the opt-in families in os_ui::icon_packs::PACKS after Default.
//! Transport, editing and window controls use separately drawn silhouettes per family.
//! File and utility glyphs use each family's document, folder and instrument shapes.

use super::Icon;
use os_ui::tabler::TablerIcon;

pub struct Art {
    pub shape: TablerIcon,
    /// Exact working point for the cursor, in the same coordinates as the artwork.
    pub hotspot: Option<(f32, f32)>,
}

impl Art {
    const fn outline(d: &'static str) -> Self {
        Self { shape: TablerIcon { filled: false, d }, hotspot: None }
    }

    const fn filled(d: &'static str) -> Self {
        Self { shape: TablerIcon { filled: true, d }, hotspot: None }
    }

    const fn tip(mut self, x: f32, y: f32) -> Self {
        self.hotspot = Some((x, y));
        self
    }
}

